payload.arguments:
{"command":"$repo = [System.IO.Path]::GetFullPath('D:\CommonTools')
$nested = @(
    '.codex/.tmp/marketplaces/ponytail',
    '.codex/.tmp/plugins',
    '.codex/memories',
    '.codex/vendor_imports/skills',
    'LvZhou/.obsidian/plugins/claudian'
)
$tempRoot = Join-Path $env:TEMP ("CommonToolsNestedGit_" + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $tempRoot | Out-Null
$moved = @()
try {
    git -C $repo rm -r --cached -- $nested
    for ($i = 0; $i -lt $nested.Count; $i++) {
        $nestedRoot = [System.IO.Path]::GetFullPath((Join-Path $repo $nested[$i]))
        if (-not $nestedRoot.StartsWith($repo + [System.IO.Path]::DirectorySeparatorChar, [System.StringComparison]::OrdinalIgnoreCase)) { throw "嵌套路径越出仓库：$nestedRoot" }
        $gitMeta = Join-Path $nestedRoot '.git'
        if (Test-Path -LiteralPath $gitMeta) {
            $backup = Join-Path $tempRoot $i
            Move-Item -LiteralPath $gitMeta -Destination $backup
            $moved += [pscustomobject]@{ Source = $gitMeta; Backup = $backup }
        }
    }
    git -C $repo add -A
}
finally {
    foreach ($item in $moved) {
        if (Test-Path -LiteralPath $item.Backup) {
            Move-Item -LiteralPath $item.Backup -Destination $item.Source
        }
    }
    if ((Test-Path -LiteralPath $tempRoot) -and -not (Get-ChildItem -LiteralPath $tempRoot -Force)) {
        Remove-Item -LiteralPath $tempRoot
    }
}
git -C $repo commit --amend --no-edit","workdir":"D:\CommonTools","timeout_ms":120000}

